/// <summary>
/// PricingAttribute of table <c>InventTable</c> field grossDepth.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableGrossDepth extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, grossDepth);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Real);
    InventTable inventTable;
    while select grossDepth from inventTable
        group by grossDepth
    {
        ret.add(inventTable.grossDepth);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, grossDepth));
    qbr.value(queryValue(_value));
}
